// Velocidade média humana (caracteres por segundo)
const CPS = 3.5;

// Delay mínimo e máximo absoluto (segurança)
const MIN_DELAY = 5;   // segundos
const MAX_DELAY = 60;  // segundos

for (const item of items) {

  const mensagem = item.json.output || item.json.message || "";
  const tamanho = mensagem.length;

  // Tempo base calculado pela quantidade de caracteres
  let tempoBase = tamanho / CPS;

  // Adiciona variação aleatória de -20% a +30%
  const variacao = tempoBase * (Math.random() * 0.5 - 0.2);
  let tempoFinal = tempoBase + variacao;

  // Garante limites mínimos e máximos
  tempoFinal = Math.max(MIN_DELAY, Math.min(MAX_DELAY, tempoFinal));

  // Arredonda
  tempoFinal = Math.round(tempoFinal);

  item.json.delaySeconds = tempoFinal;
  item.json.delayMs = tempoFinal * 1000;
  item.json.delayHuman = `${tempoFinal}s`;
}

return items;
